import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.CK6jtcgr.js";const u=JSON.parse('{"title":"Governed Cybernetic Stack","description":"","frontmatter":{},"headers":[],"relativePath":"guide/governed-cybernetic-stack.md","filePath":"guide/governed-cybernetic-stack.md"}'),o={name:"guide/governed-cybernetic-stack.md"};function r(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="governed-cybernetic-stack" tabindex="-1">Governed Cybernetic Stack <a class="header-anchor" href="#governed-cybernetic-stack" aria-label="Permalink to &quot;Governed Cybernetic Stack&quot;">​</a></h1><p>This guide expands the homepage thesis.</p><p>SocioProphet is cybernetic infrastructure for <strong>human education, human health, and shared global human knowledge</strong>.</p><p>The platform is described as a <strong>governed cybernetic stack</strong>, not merely as a three-layer system. The public repos and public website already imply a multi-layer operating model with governance, semantic interoperability, deterministic protocol transport, bounded execution, workspace control, academy/commons surfaces, and opt-in community automation.</p><h2 id="constitutional-domains" tabindex="-1">Constitutional domains <a class="header-anchor" href="#constitutional-domains" aria-label="Permalink to &quot;Constitutional domains&quot;">​</a></h2><h3 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h3><p>Education is how attention becomes skill, judgment, disciplined thought, and durable institutional capability.</p><h3 id="health" tabindex="-1">Health <a class="header-anchor" href="#health" aria-label="Permalink to &quot;Health&quot;">​</a></h3><p>Health is how the biological and cognitive basis of agency is preserved. This is framed carefully as governance, consent, evidence, longitudinal memory, coordination, and human care infrastructure — not as autonomous clinical authority.</p><h3 id="shared-global-human-knowledge" tabindex="-1">Shared global human knowledge <a class="header-anchor" href="#shared-global-human-knowledge" aria-label="Permalink to &quot;Shared global human knowledge&quot;">​</a></h3><p>Shared global human knowledge is how insight survives individual lives and becomes civilizational memory rather than being repeatedly lost and repurchased.</p><h2 id="primary-thesis" tabindex="-1">Primary thesis <a class="header-anchor" href="#primary-thesis" aria-label="Permalink to &quot;Primary thesis&quot;">​</a></h2><p>The central problem of the machine age is not lack of information. It is the waste, fragmentation, and misallocation of trained human attention.</p><p>SocioProphet exists to solve that problem.</p><p>We build a governed cybernetic system that helps people and institutions educate better, care better, remember better, and coordinate better. Our premise is simple: trained human attention is civilization’s most precious productive force. Machines must not replace it. Machines must protect it, focus it, extend it, and leave behind evidence that compounds future human learning.</p><h2 id="human-machine-symbiosis" tabindex="-1">Human-machine symbiosis <a class="header-anchor" href="#human-machine-symbiosis" aria-label="Permalink to &quot;Human-machine symbiosis&quot;">​</a></h2><p>Our view is symbiosis, not substitution.</p><p>Humans choose ends.<br> Machines assist with means.<br> Evidence governs the loop.</p><p>Humans define legitimacy, priorities, approvals, red lines, and moral boundaries. Machines help retrieve, compare, synthesize, simulate, coordinate, and execute bounded operations under visible policy. Every consequential action must be inspectable. Every important state change must be attributable. Every durable action must leave evidence. Every irreversible action remains under stronger human control.</p><h2 id="multi-layer-stack" tabindex="-1">Multi-layer stack <a class="header-anchor" href="#multi-layer-stack" aria-label="Permalink to &quot;Multi-layer stack&quot;">​</a></h2><h3 id="constitutional-layer" tabindex="-1">Constitutional layer <a class="header-anchor" href="#constitutional-layer" aria-label="Permalink to &quot;Constitutional layer&quot;">​</a></h3><p>Institutions define purpose, approvals, red lines, protected domains, and escalation authority.</p><h3 id="human-layer" tabindex="-1">Human layer <a class="header-anchor" href="#human-layer" aria-label="Permalink to &quot;Human layer&quot;">​</a></h3><p>Artifacts, consent, capability proofs, identity, and human-centered policy surfaces are first-class objects.</p><h3 id="semantic-layer" tabindex="-1">Semantic layer <a class="header-anchor" href="#semantic-layer" aria-label="Permalink to &quot;Semantic layer&quot;">​</a></h3><p>Ontologies, vocabularies, mappings, validation shapes, and semantic contracts make knowledge interoperable rather than merely searchable.</p><h3 id="protocol-layer" tabindex="-1">Protocol layer <a class="header-anchor" href="#protocol-layer" aria-label="Permalink to &quot;Protocol layer&quot;">​</a></h3><p>Deterministic authenticated transport makes actions, messages, and proofs reproducible across implementations.</p><h3 id="execution-layer" tabindex="-1">Execution layer <a class="header-anchor" href="#execution-layer" aria-label="Permalink to &quot;Execution layer&quot;">​</a></h3><p>Bounded agents plan, validate, run, emit evidence, and support replay and rollback under governance.</p><h3 id="workspace-layer" tabindex="-1">Workspace layer <a class="header-anchor" href="#workspace-layer" aria-label="Permalink to &quot;Workspace layer&quot;">​</a></h3><p>Composition, manifests, locks, runners, release surfaces, and governance gates make the system operable as an actual platform.</p><h3 id="academy-and-commons-layer" tabindex="-1">Academy and commons layer <a class="header-anchor" href="#academy-and-commons-layer" aria-label="Permalink to &quot;Academy and commons layer&quot;">​</a></h3><p>Learning objects, transcripts, claims, rationales, corrections, evaluations, and contribution histories become durable knowledge fabric.</p><h3 id="community-automation-layer" tabindex="-1">Community automation layer <a class="header-anchor" href="#community-automation-layer" aria-label="Permalink to &quot;Community automation layer&quot;">​</a></h3><p>Opt-in build, catalog, training, and update workflows extend the system into the wider SourceOS commons without making that automation mandatory.</p><h2 id="what-makes-socioprophet-different" tabindex="-1">What makes SocioProphet different <a class="header-anchor" href="#what-makes-socioprophet-different" aria-label="Permalink to &quot;What makes SocioProphet different&quot;">​</a></h2><p>Most AI products optimize for content generation, attention capture, and increasing machine autonomy.</p><p>SocioProphet must optimize for <strong>increasing human capability per unit of machine assistance</strong>.</p><p>Where others extract attention, we cultivate it.<br> Where others generate more content, we build better understanding.<br> Where others centralize intelligence inside opaque black boxes, we build governed, inspectable, replayable systems.<br> Where others promise autonomy first, we insist on evidence, policy, and human sovereignty first.</p>',40)])])}const p=a(o,[["render",r]]);export{u as __pageData,p as default};
